/*
 * Boundless generator for buildai-knowledge-database-coordinator — item 179.
 * Dual node+browser: node prints JSONL records; browser registers with JAHDB.
 * Deterministic: same seed + topic = same record. HARD_CAP = 1e15.
 */
'use strict';
var SLUG = 'buildai-knowledge-database-coordinator';
var PREFIX = 'JAH-BAI-';
var HARD_CAP = 1e15;
var ARCHETYPES = [{"kind": "term-extract", "title": "Extracting Search Terms", "body": "Queries split on non-alphanumerics and drop one-letter terms. The demo extracts terms from a sample query.", "demoCode": "var q='Signature Spec Catalog!';var t=q.toLowerCase().split(/[^a-z0-9]+/).filter(function(x){return x.length>1;});return t.join(', ');", "ladder": "simple", "vstat": "tested", "caps": ["keyword search"]}, {"kind": "url-build", "title": "Building a Database Page URL", "body": "Page URLs are the canonical base plus the slug. The demo builds one at generation time.", "demoCode": "var base='https://justinahiggins614-cmyk.github.io/jah-databases/db/';return base+'equations/';", "ladder": "simple", "vstat": "tested", "caps": ["url wiring"]}, {"kind": "score-demo", "title": "Scoring a Match", "body": "Slug hits weigh 5, name 3, tagline 2, full text 1. The demo scores a sample entry for the term calculator.", "demoCode": "var db={slug:'calculators',name:'Calculators Database',tagline:'every calculator'};var s=0;if(db.slug.indexOf('calculator')>=0)s+=5;if(db.name.toLowerCase().indexOf('calculator')>=0)s+=3;return 'score: '+s;", "ladder": "competitive", "vstat": "tested", "caps": ["relevance scoring"]}, {"kind": "rank-demo", "title": "Ranking Two Candidates", "body": "Higher scores sort first, deterministically. The demo ranks two sample databases.", "demoCode": "var a={slug:'calculators',score:8},b={slug:'equations',score:0};var r=[a,b].sort(function(x,y){return y.score-x.score;});return r.map(function(x){return x.slug;}).join(' > ');", "ladder": "competitive", "vstat": "tested", "caps": ["ranked retrieval"]}, {"kind": "lookup-hit", "title": "Resolving a Known Slug", "body": "Lookup is an exact case-insensitive slug match. The demo resolves one.", "demoCode": "var dbs=[{slug:'equations'}];var k='EQUATIONS'.toLowerCase();var hit=dbs.filter(function(d){return d.slug===k;})[0];return hit?'found: '+hit.slug:'not found';", "ladder": "simple", "vstat": "tested", "caps": ["exact lookup"]}, {"kind": "lookup-miss", "title": "Handling an Unknown Slug", "body": "Unknown slugs return an explicit error. The demo shows the miss path.", "demoCode": "var dbs=[{slug:'equations'}];var hit=dbs.filter(function(d){return d.slug==='nope';})[0];return hit?'found':'error: no database with slug: nope';", "ladder": "simple", "vstat": "tested", "caps": ["error handling"]}, {"kind": "integrity-demo", "title": "Checking Count Integrity", "body": "Declared counts must equal loaded entries. The demo checks a miniature manifest.", "demoCode": "var m={database_count:3,databases:[1,2,3]};return 'integrity: '+(m.database_count===m.databases.length);", "ladder": "simple", "vstat": "tested", "caps": ["integrity checking"]}, {"kind": "limit-note", "title": "Read-Only by Design", "body": "The coordinator never writes the manifest or fetches live pages. This record states the boundary \u2014 proposed extensions, not promises.", "demoCode": "return 'read-only over the local manifest; live page fetching is proposed future work';", "ladder": "simple", "vstat": "proposed", "caps": ["honest limits"]}];

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function generate(seed, opts) {
  opts = opts || {};
  seed = Math.floor(Math.abs(Number(seed) || 1));
  var rng = mulberry32(seed);
  var ai = ARCHETYPES[Math.floor(rng() * ARCHETYPES.length)];
  var topic = opts.topic || 'the Signature engineering system';
  var idx = Math.floor(rng() * 1000);
  var demoOutput;
  try { demoOutput = String((new Function(ai.demoCode))()); }
  catch (e) { demoOutput = 'demo error: ' + String(e && e.message || e); }
  var title = ai.title + ' — ' + topic + ' #' + (idx + 1);
  return {
    id: PREFIX + 'G' + String(seed).padStart(4, '0') + '-' + String(idx).padStart(3, '0'),
    slug: SLUG, title: title, t: title, g: 'engineering systems', c: 1,
    description: ai.title + ': a generated record for ' + topic + '.',
    body: ai.body + ' This record was produced by the boundless generator for ' + topic +
      '; its demonstration ran at generation time and the captured output is stored below.',
    capabilities: ai.caps,
    demo: { program: ai.demoCode, output: demoOutput.slice(0, 2000) },
    provenance: 'Generated by the boundless generator for ' + SLUG + ' (item 179), seed ' + seed + '.',
    licensing: 'Original Signature software. Property of Justin Addam Higgins (JAH).',
    src: 'generated', edition: 'signature', ladder_rank: ai.ladder,
    generator: 'jahdb-buildai-knowledge-database-coordinator-1.0', verification_status: ai.vstat,
    links: [], record_kind: 'knowledge coordinator record'
  };
}

function validate(r) {
  var errors = [];
  ['id', 'title', 'body', 'demo', 'src', 'edition', 'verification_status'].forEach(function (f) {
    if (r[f] === undefined || r[f] === null || r[f] === '') errors.push('missing ' + f);
  });
  if (r.demo && (r.demo.program === undefined || r.demo.output === undefined))
    errors.push('demo needs program and output');
  return { ok: errors.length === 0, errors: errors };
}

var api = { generate: generate, validate: validate, HARD_CAP: HARD_CAP, SLUG: SLUG };

if (typeof module !== 'undefined' && module.exports) module.exports = api;
if (typeof window !== 'undefined' && window.JAHDB && window.JAHDB.registerGenerator)
  window.JAHDB.registerGenerator(SLUG, api);
if (typeof process !== 'undefined' && process.argv && process.argv[1] &&
    process.argv[1].indexOf('gen-') >= 0) {
  (function main() {
    var n = 8, seed = 1, topic = null;
    var a = process.argv.slice(2);
    for (var i = 0; i < a.length; i++) {
      if (a[i] === '--n') n = parseInt(a[++i], 10);
      if (a[i] === '--seed') seed = parseInt(a[++i], 10);
      if (a[i] === '--topic') topic = a[++i];
    }
    if (!(n >= 1 && n <= HARD_CAP)) { console.error('n out of range'); process.exit(1); }
    for (var k = 0; k < n; k++) {
      var r = generate(seed + k, { topic: topic });
      var v = validate(r);
      if (!v.ok) { console.error('invalid record: ' + v.errors.join('; ')); process.exit(1); }
      console.log(JSON.stringify(r));
    }
  })();
}
